walker Traverse {
    has visited: int = 0;

    can visit_item with Item entry {
        self.visited += 1;
        report here.value;
        if self.visited >= 10000 {
            disengage;
        }
        visit [->:Next:->];
    }
}

# Sum all values in the list

walker load_feed {
    has search_query: str = "",
        feed: list[TweetView] = [],
        reports: list[list[TweetView]] = [];

    can run with Root entry {
        visit [-->[?:Profile]];
    }

    can collect with Profile entry {
        # TEMPORARY: typed Post edges so the TTG planner can include Tweets
        # in the prefetch plan. Real fix is runtime-side (planner should
        # handle generic out-edges too, with cardinality guards).
        visit [->:Post:->[?:Tweet]];
        visit [->:Follow:->[?:Profile]->:Post:->[?:Tweet]];
    }

    can gather with Tweet entry {
        self.feed.append(here.to_view());
    }

    can deliver with Root exit {
        result = self.feed;
        if self.search_query {
            q = self.search_query.lower().strip();
            result = [
                t
                for t in result
                if q in t.content.lower()
            ];
        }
        result.sort(key=lambda (t: TweetView) { t.created_at; }, reverse=True);
        report result;
    }
}

walker load_channel {
    can gather_messages with Channel entry;
    can collect_message with Message entry;
}

walker VisibleFolderTree {
    has start_id: str = "",
        entries: list[FolderTreeEntry] = [],
        depths: dict[str, int] = {},
        paths: dict[str, str] = {},
        reports: list[FolderTreeView] = [];

    can walk with Folder entry;
    can done with Folder exit;
}

walker ProjectBoard {
    has projects: list[dict] = [],
        engineers: list[dict] = [],
        issues: list[dict] = [];

    can start with Root entry {
        visit [-->[?:Project]];
    }
    can project with Project entry {
        self.projects.append({"id": jid(here), "name": here.name});
        visit [->:HasEngineer:->[?:Engineer]];
        visit [->:HasIssue:->[?:Issue]];
    }

    can engineer with Engineer entry {
        self.engineers.append(
            {"id": jid(here), "name": here.name, "active": here.active}
        );
    }
    can issue with Issue entry {
        self.issues.append(_issue_view(here));
    }
    can finish with Root exit {
        report {
            "projects": self.projects,
            "engineers": self.engineers,
            "issues": self.issues
        };
    }
}

walker ExpenseBoard {
    has expenses: list[dict] = [];

    can start with Root entry {
        visit [-->[?:Expense]];
    }
    can collect with Expense entry {
        self.expenses.append(_expense_view(here));
    }
    can finish with Root exit {
        report {"expenses": self.expenses};
    }
}

walker Inventory {
    has warehouses: list[dict] = [],
        skus: list[dict] = [],
        lots: list[dict] = [],
        reservations: list[dict] = [],
        dispatches: list[dict] = [];

    can start with Root entry {
        visit [-->[?:Warehouse]];
    }
    can warehouse with Warehouse entry {
        self.warehouses.append({"id": jid(here), "name": here.name});
        visit [->:HasSKU:->[?:SKU]];
        visit [->:Stocks:->[?:Lot]];
        visit [->:Holds:->[?:Reservation]];
        visit [->:HasDispatch:->[?:Dispatch]];
    }

    can sku with SKU entry {
        self.skus.append({"id": jid(here), "name": here.name, "code": here.code});
    }
    can lot with Lot entry {
        sku = [here->:ForSKU:->[?:SKU]][0];
        self.lots.append(
            {
                "id": jid(here),
                "sku_id": jid(sku),
                "sequence": here.sequence,
                "received": here.received,
                "available": here.available,
                "dispatched": here.dispatched
            }
        );
    }

    can reservation with Reservation entry {
        self.reservations.append(_reservation_view(here));
    }
    can dispatch with Dispatch entry {
        reservation = [here->:ForReservation:->[?:Reservation]][0];
        self.dispatches.append(
            {
                "id": jid(here),
                "reservation_id": jid(reservation),
                "quantity": here.quantity,
                "reference": here.reference
            }
        );
    }

    can finish with Root exit {
        report {
            "warehouses": self.warehouses,
            "skus": self.skus,
            "lots": self.lots,
            "reservations": self.reservations,
            "dispatches": self.dispatches
        };
    }
}

walker ClinicSchedule {
    has clinics: list[dict] = [],
        practitioners: list[dict] = [],
        slots: list[dict] = [];

    can start with Root entry {
        visit [-->[?:Clinic]];
    }
    can clinic with Clinic entry {
        self.clinics.append({"id": jid(here), "name": here.name, "date": here.date});
        visit [->:HasPractitioner:->[?:Practitioner]];
    }

    can practitioner with Practitioner entry {
        self.practitioners.append(
            {"id": jid(here), "name": here.name, "specialty": here.specialty}
        );
        visit [->:OffersSlot:->[?:Slot]];
    }

    can slot with Slot entry {
        owner = [here<-:OffersSlot:<-[?:Practitioner]][0];
        self.slots.append(
            {
                "id": jid(here),
                "practitioner_id": jid(owner),
                "start_minute": here.start_minute,
                "duration": here.duration,
                "appointments": [
                    {"id": jid(item), "patient": item.patient, "status": item.status}
                    for item in [here->:HasAppointment:->[?:Appointment]]
                ]
            }
        );
    }

    can finish with Root exit {
        report {
            "clinics": self.clinics,
            "practitioners": self.practitioners,
            "slots": self.slots
        };
    }
}

walker LearningDashboard {
    has courses: list[dict] = [],
        enrollments: list[dict] = [];

    can start with Root entry {
        visit [-->[?:Course]];
        visit [-->[?:Enrollment]];
    }
    can course with Course entry {
        modules = [];
        for module in [here->:HasModule:->[?:Module]] {
            lessons = [];
            for lesson in [module->:HasLesson:->[?:Lesson]] {
                lessons.append(
                    {
                        "id": jid(lesson),
                        "title": lesson.title,
                        "position": lesson.position,
                        "minutes": lesson.minutes,
                        "requires": [
                            jid(item) for item in [lesson->:Requires:->[?:Lesson]]
                        ]
                    }
                );
            }
            modules.append(
                {
                    "id": jid(module),
                    "title": module.title,
                    "position": module.position,
                    "lessons": lessons
                }
            );
        }
        self.courses.append({"id": jid(here), "title": here.title, "modules": modules});
    }

    can enrollment with Enrollment entry {
        self.enrollments.append(_enrollment_view(here));
    }
    can finish with Root exit {
        report {"courses": self.courses, "enrollments": self.enrollments};
    }
}

walker LibraryCatalog {
    has libraries: list[dict] = [],
        patrons: list[dict] = [],
        titles: list[dict] = [],
        loans: list[dict] = [];

    can start with Root entry {
        visit [-->[?:Library]];
    }
    can library with Library entry {
        self.libraries.append({"id": jid(here), "name": here.name});
        visit [->:HasPatron:->[?:Patron]];
        visit [->:HasTitle:->[?:Title]];
        visit [->:HasLoan:->[?:Loan]];
    }

    can patron with Patron entry {
        self.patrons.append({"id": jid(here), "name": here.name});
    }
    can title with Title entry {
        holds = [];
        for hold in [here->:HasHold:->[?:Hold]] {
            patron = [hold->:RequestedBy:->[?:Patron]][0];
            holds.append(
                {
                    "id": jid(hold),
                    "patron_id": jid(patron),
                    "patron": patron.name,
                    "position": hold.position,
                    "status": hold.status
                }
            );
        }
        self.titles.append(
            {
                "id": jid(here),
                "name": here.name,
                "edition": here.edition,
                "copies": [
                    {
                        "id": jid(copy),
                        "barcode": copy.barcode,
                        "available": copy.available
                    } for copy in [here->:HasCopy:->[?:Copy]]
                ],
                "holds": holds
            }
        );
    }

    can loan with Loan entry {
        patron = [here->:Borrower:->[?:Patron]][0];
        copy = [here->:LoanCopy:->[?:Copy]][0];
        title = [copy<-:HasCopy:<-[?:Title]][0];
        self.loans.append(
            {
                "id": jid(here),
                "patron_id": jid(patron),
                "patron": patron.name,
                "copy_id": jid(copy),
                "title_id": jid(title),
                "title": title.name,
                "status": here.status
            }
        );
    }

    can finish with Root exit {
        report {
            "libraries": self.libraries,
            "patrons": self.patrons,
            "titles": self.titles,
            "loans": self.loans
        };
    }
}

walker EventCatalog {
    has venues: list[dict] = [],
        events: list[dict] = [];

    can start with Root entry {
        visit [-->[?:Venue]];
    }
    can venue with Venue entry {
        self.venues.append({"id": jid(here), "name": here.name});
        visit [->:Hosts:->[?:Event]];
    }
    can event with Event entry {
        sections = [];
        for section in [here->:HasSection:->[?:Section]] {
            sections.append(
                {
                    "id": jid(section),
                    "name": section.name,
                    "seats": [
                        {
                            "id": jid(seat),
                            "label": seat.label,
                            "price_cents": seat.price_cents,
                            "status": seat.status
                        } for seat in [section->:HasSeat:->[?:Seat]]
                    ]
                }
            );
        }
        self.events.append(
            {
                "id": jid(here),
                "title": here.title,
                "sections": sections,
                "bookings": [
                    _booking_view(booking)
                    for booking in [here->:HasBooking:->[?:Booking]]
                ]
            }
        );
    }

    can finish with Root exit {
        report {"venues": self.venues, "events": self.events};
    }
}

