walker PantryBoard {
    has ingredients: list[dict] = [],
        recipes: list[dict] = [],
        meals: list[dict] = [];

    can start with Root entry {
        visit [-->[?:Ingredient]];
        visit [-->[?:Recipe]];
        visit [-->[?:Meal]];
    }
    can ingredient with Ingredient entry {
        self.ingredients.append(
            {
                "id": jid(here),
                "name": here.name,
                "initial": here.initial,
                "units": here.units,
                "purchased": sum(p.units for p in [here->:Bought:->[?:Purchase]]),
                "consumed": sum(c.units for c in [here->:Consumed:->[?:Consumption]])
            }
        );
    }

    can recipe with Recipe entry {
        self.recipes.append({"id": jid(here), "name": here.name});
    }
    can meal with Meal entry {
        self.meals.append(
            {
                "id": jid(here),
                "name": here.name,
                "servings": here.servings,
                "status": here.status
            }
        );
    }
    can finish with Root exit {
        report {
            "ingredients": self.ingredients,
            "recipes": self.recipes,
            "meals": self.meals
        };
    }
}

walker Itinerary {
    has journeys: list[dict] = [];

    can start with Root entry {
        visit [-->[?:Journey]];
    }
    can journey with Journey entry {
        stops = [
            {
                "id": jid(s),
                "name": s.name,
                "day": s.day,
                "position": s.position,
                "capacity": s.capacity,
                "booked": sum(
                    b.guests
                    for b in [s->:HasStay:->[?:Stay]]
                    if b.active
                ),
                "bookings": [
                    {"id": jid(b), "guests": b.guests, "active": b.active}
                    for b in [s->:HasStay:->[?:Stay]]
                ]
            } for s in [here->:HasStop:->[?:Stop]]
        ];
        stops.sort(key=lambda (s: dict) { s["position"]; });
        self.journeys.append(
            {"id": jid(here), "name": here.name, "days": here.days, "stops": stops}
        );
    }

    can finish with Root exit {
        report {"journeys": self.journeys};
    }
}

walker RouteBoard {
    has depots: list[dict] = [],
        routes: list[dict] = [],
        parcels: list[dict] = [];

    can start with Root entry {
        visit [-->[?:Depot]];
    }
    can depot with Depot entry {
        self.depots.append({"id": jid(here), "name": here.name});
        visit [->:HasRoute:->[?:Route]];
        visit [->:HasParcel:->[?:Parcel]];
    }
    can parcel with Parcel entry {
        self.parcels.append(
            {
                "id": jid(here),
                "label": here.label,
                "weight": here.weight,
                "status": here.status,
                "scans": [s.kind for s in [here->:HasScan:->[?:Scan]]]
            }
        );
    }
    can route with Route entry {
        stops = [];
        for s in [here->:HasStop:->[?:Stop]] {
            p = [s->:Carries:->[?:Parcel]][0];
            stops.append(
                {
                    "id": jid(s),
                    "position": s.position,
                    "status": s.status,
                    "parcel_id": jid(p),
                    "label": p.label
                }
            );
        }
        stops.sort(key=lambda (s: dict) { s["position"]; });
        self.routes.append(
            {
                "id": jid(here),
                "name": here.name,
                "capacity": here.capacity,
                "loaded": here.loaded,
                "stops": stops,
                "complete": bool(stops)
                    and all(s["status"] == "delivered" for s in stops)
            }
        );
    }

    can finish with Root exit {
        report {"depots": self.depots, "routes": self.routes, "parcels": self.parcels};
    }
}

walker HiringBoard {
    has jobs: list[dict] = [],
        candidates: list[dict] = [];

    can start with Root entry {
        visit [-->[?:Job]];
        visit [-->[?:Candidate]];
    }
    can candidate with Candidate entry {
        self.candidates.append({"id": jid(here), "name": here.name});
    }
    can job with Job entry {
        apps = [];
        for a in [here->:HasApplication:->[?:Application]] {
            c = [a->:CandidateRef:->[?:Candidate]][0];
            apps.append(
                {
                    "id": jid(a),
                    "candidate": c.name,
                    "status": a.status,
                    "interviews": [
                        {
                            "id": jid(i),
                            "round": i.round,
                            "scores": [s.score for s in [i->:HasScore:->[?:Scorecard]]]
                        } for i in [a->:HasInterview:->[?:Interview]]
                    ]
                }
            );
        }
        self.jobs.append(
            {
                "id": jid(here),
                "title": here.title,
                "positions": here.positions,
                "threshold": here.threshold,
                "applications": apps
            }
        );
    }

    can finish with Root exit {
        report {"jobs": self.jobs, "candidates": self.candidates};
    }
}

walker SalesBoard {
    has accounts: list[dict] = [],
        won_cents: int = 0;

    can start with Root entry {
        visit [-->[?:Account]];
    }
    can account with Account entry {
        opportunities = [];
        for o in [here->:HasOpportunity:->[?:Opportunity]] {
            opportunities.append(
                {
                    "id": jid(o),
                    "title": o.title,
                    "stage": o.stage,
                    "amount_cents": o.amount_cents,
                    "activities": [a.note for a in [o->:HasActivity:->[?:Activity]]],
                    "quotes": [
                        {
                            "id": jid(q),
                            "total_cents": q.quantity * q.unit_cents,
                            "accepted": q.accepted
                        } for q in [o->:HasQuote:->[?:Quote]]
                    ]
                }
            );
            if o.stage == "won" {
                self.won_cents += o.amount_cents;
            }
        }
        self.accounts.append(
            {
                "id": jid(here),
                "name": here.name,
                "contacts": [c.name for c in [here->:HasContact:->[?:Contact]]],
                "opportunities": opportunities
            }
        );
    }

    can finish with Root exit {
        report {"accounts": self.accounts, "won_cents": self.won_cents};
    }
}

walker ReviewBoard {
    has proposals: list[dict] = [],
        reviewers: list[dict] = [];

    can start with Root entry {
        visit [-->[?:Proposal]];
        visit [-->[?:Reviewer]];
    }
    can reviewer with Reviewer entry {
        self.reviewers.append(
            {
                "id": jid(here),
                "name": here.name,
                "conflicts": [jid(p) for p in [here->:Conflict:->[?:Proposal]]]
            }
        );
    }
    can proposal with Proposal entry {
        assignments = [];
        total = 0;
        count = 0;
        for a in [here->:HasAssignment:->[?:Assignment]] {
            r = [a->:ReviewerRef:->[?:Reviewer]][0];
            scores = [
                v.merit * 2 + v.feasibility for v in [a->:HasReview:->[?:Review]]
            ];
            assignments.append(
                {
                    "id": jid(a),
                    "reviewer": r.name,
                    "submitted": a.submitted,
                    "scores": scores
                }
            );
            if scores {
                total += scores[0];
                count += 1;
            }
        }
        self.proposals.append(
            {
                "id": jid(here),
                "title": here.title,
                "released": here.released,
                "assignments": assignments,
                "score_total": total,
                "review_count": count
            }
        );
    }

    can finish with Root exit {
        report {"proposals": self.proposals, "reviewers": self.reviewers};
    }
}

walker LabBoard {
    has samples: list[dict] = [],
        batches: list[dict] = [],
        assays: list[dict] = [];

    can start with Root entry {
        visit [-->[?:Sample]];
        visit [-->[?:Batch]];
        visit [-->[?:Assay]];
    }
    can sample with Sample entry {
        self.samples.append(
            {
                "id": jid(here),
                "name": here.name,
                "initial": here.initial,
                "remaining": here.remaining,
                "aliquots": [
                    {
                        "id": jid(a),
                        "number": a.number,
                        "volume": a.volume,
                        "assigned": bool([a<-:Includes:<-[?:Batch]]),
                        "results": [
                            {
                                "value": r.value,
                                "passed": r.passed,
                                "sequence": r.sequence
                            } for r in [a->:HasResult:->[?:Result]]
                        ]
                    } for a in [here->:HasAliquot:->[?:Aliquot]]
                ]
            }
        );
    }
    can batch with Batch entry {
        self.batches.append(
            {
                "id": jid(here),
                "name": here.name,
                "released": here.released,
                "aliquots": [jid(a) for a in [here->:Includes:->[?:Aliquot]]]
            }
        );
    }
    can assay with Assay entry {
        self.assays.append(
            {
                "id": jid(here),
                "name": here.name,
                "lower": here.lower,
                "upper": here.upper
            }
        );
    }
    can finish with Root exit {
        report {
            "samples": self.samples,
            "batches": self.batches,
            "assays": self.assays
        };
    }
}

walker AssetBoard {
    has assets: list[dict] = [],
        technicians: list[dict] = [],
        parts: list[dict] = [];

    can start with Root entry {
        visit [-->[?:Asset]];
        visit [-->[?:Technician]];
        visit [-->[?:Part]];
    }
    can asset with Asset entry {
        self.assets.append(
            {
                "id": jid(here),
                "name": here.name,
                "status": here.status,
                "inspections": [
                    {"issue": i.issue, "severity": i.severity}
                    for i in [here->:HasInspection:->[?:Inspection]]
                ],
                "orders": [
                    {
                        "id": jid(o),
                        "number": o.number,
                        "status": o.status,
                        "uses": [
                            {
                                "quantity": u.quantity,
                                "part_id": jid([u->:PartRef:->[?:Part]][0])
                            } for u in [o->:UsesPart:->[?:PartUse]]
                        ]
                    } for o in [here->:HasOrder:->[?:WorkOrder]]
                ]
            }
        );
    }
    can technician with Technician entry {
        self.technicians.append({"id": jid(here), "name": here.name});
    }
    can part with Part entry {
        self.parts.append(
            {
                "id": jid(here),
                "name": here.name,
                "initial": here.initial,
                "stock": here.stock
            }
        );
    }
    can finish with Root exit {
        report {
            "assets": self.assets,
            "parts": self.parts,
            "technicians": self.technicians
        };
    }
}

